@Injectable({ providedIn: 'root' })
export class I18nService {
  private readonly languageSubject = new BehaviorSubject<Language>(this.detectLanguage());
  readonly language$ = this.languageSubject.asObservable();
  get language(): Language { return this.languageSubject.value; }
  route(page: string): string { return `/${this.language}/${page}`; }
  pageFromPath(path: string): string {
    const aliases: Record<string, string> = { inicio: 'home', sobre: 'about', experiencia: 'experience', projetos: 'projects', conquistas: 'projects', contato: 'contact', laboratorio: 'lab' };
    return aliases[path] || path || 'home';
  }
  translate(key: string): string { return MESSAGES[key]?.[this.language] ?? EXTRA_MESSAGES[key]?.[this.language] ?? key; }
  setLanguage(language: Language): void {
    this.languageSubject.next(language);
    try { localStorage.setItem('portfolio-language', language); } catch { /* storage may be unavailable */ }
    if (typeof document !== 'undefined') document.documentElement.lang = language === 'pt' ? 'pt-BR' : language;
  }
  private detectLanguage(): Language {
    try {
      const saved = localStorage.getItem('portfolio-language');
      if (saved === 'pt' || saved === 'en' || saved === 'es') return saved;
    } catch { /* storage may be unavailable */ }
    const browserLanguage = typeof navigator === 'undefined' ? 'en' : navigator.language.toLowerCase().split('-')[0];
    return browserLanguage === 'pt' || browserLanguage === 'es' ? browserLanguage : 'en';
  }
}

@Pipe({ name: 't', pure: false })
export class TranslatePipe implements PipeTransform {
  constructor(private readonly i18n: I18nService) {}
  transform(key: string): string { return this.i18n.translate(key); }
}

@Pipe({ name: 'localizedRoute', pure: false })
export class LocalizedRoutePipe implements PipeTransform {
  constructor(private readonly i18n: I18nService) {}
  transform(page: string): string { return this.i18n.route(page); }
}
